#include <stdio.h>
#include <string.h>

#define MAX_ARGS   65      /* inclusive limit, matches the original check */
#define MAX_LEN   1024     /* maximum allowed length of any argument */

int main(int argc, char **argv)
{
    /* 1. Argument count checks */
    if (argc > MAX_ARGS) {
        puts("TOO_MANY");
        return 0;
    }
    if (argc < 2) {               /* no user‑supplied arguments */
        puts("EMPTY");
        return 0;
    }

    /* 2. Length check for each supplied argument */
    for (int i = 1; i < argc; ++i) {
        if ((size_t)strlen(argv[i]) > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* 3. Compute longest common prefix of all arguments (argv[1] … argv[argc‑1]) */
    const char *first = argv[1];
    size_t prefix_len = 0;

    while (first[prefix_len] != '\0') {
        char c = first[prefix_len];
        int all_match = 1;

        for (int i = 2; i < argc; ++i) {
            if (argv[i][prefix_len] != c) {
                all_match = 0;
                break;
            }
        }

        if (!all_match) break;          /* mismatch found */
        ++prefix_len;                    /* character matches in all strings */
    }

    /* 4. Output the prefix (may be empty) followed by a newline */
    for (size_t i = 0; i < prefix_len; ++i)
        putchar(first[i]);
    putchar('\n');

    return 0;
}
